import * as React from "react";
import { graphql, Link } from "gatsby";
import HeaderMenu from "../components/HeaderMenu/HeaderMenu";
import { withLayout, LayoutProps, menuItems } from "../components/Layout";
import {
  Button,
  Segment,
  Container,
  Grid,
  Header,
  Icon,
  Image,
} from "semantic-ui-react";
import Img from "gatsby-image";

interface IndexProps extends LayoutProps {
  data: {
    file: {
      childImageSharp: ImageSharpQueryArgs;
    },
  };
}

const IndexPage = (props: IndexProps) =>
  <div>
      <HeaderMenu
        Link={Link} pathname={props.location.pathname} items={menuItems}
      />

    <Container text>
      <Segment clearing basic size="big">

        <div className="pictureContainer">
          <Img fixed={props.data.file.childImageSharp.fixed} />
        </div>
        <p>Hi!</p>

        <p>My name is Ed Schwartz.  I am a research scientist ∈ executable code analysis team 
        ⊂ threat analysis division ⊂ <a href="http://www.cert.org">CERT</a> ⊂ <a href="http://sei.cmu.edu">SEI</a> 
        ⊂ <a href="http://www.cmu.edu">CMU</a>.
        Before that, I earned my Ph.D. from CMU's <a href="http://www.cylab.cmu.edu">CyLab</a>.</p>

        <p>I'm interested in almost all aspects of computer security, but these days I usually work on
           static and dynamic binary program analysis, vulnerability discovery (e.g., fuzzing and concolic
           execution), and software security attacks and defenses (e.g., code reuse attacks).</p>

        <p>For more information on my research, take a look at my <Link to="/publications">publications</Link>.  
           I <Link to="/blog">blog</Link> about all types of technical issues, including research and general 
           thoughts on computing.  Finally, if you need anything else, feel free
          to <Link to="/contact">contact me</Link>.</p>
      </Segment>
    </Container>
    <style jsx>{`
      div.pictureContainer {
        float: right;
        padding: 1em;
      }
    `}</style>
  </div>;

export default withLayout(IndexPage);

export const query = graphql`
  query {
    file(relativePath: { eq: "imgs/ed.png" }) {
      childImageSharp {
        fixed(width: 150) {
          ...GatsbyImageSharpFixed
        }
      }
    }
  }
`;
